engine.etUserKey:
function etUserKey(ident) {
  if (!ident || typeof ident !== "object") return null;
  var first = String(ident.firstName || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "");
  if (!first) return null;
  var firstInitial = first.charAt(0);
  if (!firstInitial) return null;
  var full = String(ident.name || "").trim();
  var parts = full.split(/\s+/).filter(Boolean);
  var lastInitial = "";
  if (parts.length >= 2) {
    var last = parts[parts.length - 1].toLowerCase().replace(/[^a-z0-9]/g, "");
    if (last) lastInitial = last.charAt(0);
  }
  return lastInitial ? firstInitial + lastInitial : firstInitial;
}

// Convert a userIdentity()-style object into its display initials
// ("Andrew Nemiroff" → "AN", "Andrew" alone → "A"). Used as the
// userName written on telemetry rows and into the pushed digest, so
// the GitHub file never carries the user's full first name.

engine.etUserInitials:
function etUserInitials(ident) {
  if (!ident || typeof ident !== "object") return "";
  var first = String(ident.firstName || "").trim();
  var fi = first ? first.charAt(0).toUpperCase() : "";
  var full = String(ident.name || "").trim();
  var parts = full.split(/\s+/).filter(Boolean);
  var li = "";
  if (parts.length >= 2) {
    var last = parts[parts.length - 1];
    if (last) li = last.charAt(0).toUpperCase();
  }
  return fi + li;
}

// Today's date in YYYY-MM-DD format, optionally rebased to a passed Date.
// Used both for row keys and as the workday/weekend gate (caller checks
// the returned object's `isWeekend` flag before recording).

engine.etTodayInfo:
function etTodayInfo(nowArg) {
  var d = nowArg instanceof Date ? nowArg : new Date();
  var dow = d.getDay(); // 0 = Sun, 6 = Sat
  var y = d.getFullYear();
  var m = d.getMonth() + 1;
  var day = d.getDate();
  var pad = function (n) { return n < 10 ? "0" + n : "" + n; };
  return {
    date: y + "-" + pad(m) + "-" + pad(day),
    dow: dow,
    isWeekend: dow === 0 || dow === 6,
  };
}

// Tool-name derivation: convert a stat name like "appOpenedAskEli" into
// "ask_eli". Strips the appOpened prefix (case-insensitive) and converts
// the remainder from CamelCase to snake_case. Non-appOpened names return
// null (caller skips them).

engine.etDeriveToolName:
function etDeriveToolName(statName) {
  if (!statName || typeof statName !== "string") return null;
  var s = String(statName).trim();
  // Prefix "appOpened" is 9 chars. Case-insensitive check, then slice off.
  var PREFIX_LEN = 9;
  if (s.length <= PREFIX_LEN) return null;
  if (s.slice(0, PREFIX_LEN).toLowerCase() !== "appopened") return null;
  var rest = s.slice(PREFIX_LEN);
  if (!rest) return null;
  // CamelCase -> snake_case. Insert "_" before each uppercase letter that
  // follows a lowercase letter or another uppercase followed by lowercase.
  // Examples:
  //   "AskEli"        -> "ask_eli"
  //   "Risk"          -> "risk"
  //   "UsageRisks"    -> "usage_risks"
  //   "AdminLibraryPublisher" -> "admin_library_publisher"
  var snake = rest
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2")
    .toLowerCase();
  return snake;
}

// Prune helper: given a list of telemetry rows and today's date, return
// the subset whose `date` is more than `keepDays` calendar days old.
// Caller deletes those rows. keepDays defaults to 7.

engine.etRowsToPrune:
function etRowsToPrune(rows, todayDate, keepDays) {
  if (!Array.isArray(rows)) return [];
  var keep = (keepDays == null) ? 7 : Number(keepDays);
  var cutoff = null;
  try {
    var t = new Date(todayDate + "T00:00:00");
    if (isNaN(t.getTime())) return [];
    t.setDate(t.getDate() - keep);
    cutoff = t;
  } catch (e) { return []; }
  return rows.filter(function (r) {
    if (!r || !r.date) return false;
    var d;
    try { d = new Date(r.date + "T00:00:00"); }
    catch (e) { return false; }
    if (isNaN(d.getTime())) return false;
    return d < cutoff;
  });
}

// 2026-05-17: per-model pricing (USD per 1M tokens). Embedded with the
// digest builder so prices travel with the data. If Gemini changes
// pricing, update here + re-release the tool — old digests carry the
// price AT THE TIME the digest was built (not recomputed retroactively).
// Unknown models fall back to flash-lite pricing (cheapest tier — safer
// to under-estimate than over-estimate when alerting on cost).
//
// Source: Google AI pricing page as of 2026-05.
// Lite-preview prices are placeholder estimates — confirm before alerting
// on absolute cost numbers; for trend tracking the relative numbers work.

engine.etPriceTable:
function etPriceTable() {
  return {
    // canonical id                       input $/1M   output $/1M
    "gemini-3.1-flash-lite-preview":     { in: 0.04, out: 0.20 },
    "gemini-3.1-flash":                  { in: 0.075, out: 0.30 },
    "gemini-2.5-flash":                  { in: 0.075, out: 0.30 },
    "gemini-2.5-flash-lite-preview":     { in: 0.04, out: 0.20 },
    "gemini-2.5-pro":                    { in: 1.25, out: 5.00 },
    "gemini-1.5-pro":                    { in: 1.25, out: 5.00 },
    "gemini-1.5-flash":                  { in: 0.075, out: 0.30 },
    "_default":                          { in: 0.075, out: 0.30 }, // unknown → flash-tier
  };
}

// Merge two digests (typically remote + local) into one. Per-date
// dedupe rule: if a date exists in BOTH digests, sum toolsUsed
// counts, sum per-model token buckets, max(sessions). This handles
// the multi-computer case — Computer A and Computer B with the same
// userKey push to the same usage/<userKey>.json; without merging,
// the second push overwrites the first. With merging, both
// computers' day-rows combine into one.
// 2026-05-18 v25.

engine.etMergeDigests:
function etMergeDigests(remote, local) {
  function _emptyDigest() { return { userName: "", userKey: "", generatedAt: "", days: [] }; }
  if (!remote || typeof remote !== "object") remote = _emptyDigest();
  if (!local || typeof local !== "object") local = _emptyDigest();
  var byDate = {};
  function _ingest(digest) {
    var days = (digest && Array.isArray(digest.days)) ? digest.days : [];
    days.forEach(function (d) {
      if (!d || !d.date) return;
      var existing = byDate[d.date];
      if (!existing) {
        byDate[d.date] = JSON.parse(JSON.stringify(d));
        return;
      }
      // Merge tools (sum counts).
      var tu = existing.toolsUsed || {};
      var dt = d.toolsUsed || {};
      Object.keys(dt).forEach(function (k) {
        tu[k] = (Number(tu[k]) || 0) + (Number(dt[k]) || 0);
      });
      existing.toolsUsed = tu;
      // Merge tokens (per-model: sum prompt + candidates + calls).
      var ex = existing.tokens || {};
      var dx = d.tokens || {};
      Object.keys(dx).forEach(function (model) {
        var em = ex[model] || { promptTokens: 0, candidatesTokens: 0, calls: 0 };
        var dm = dx[model] || {};
        em.promptTokens     = (Number(em.promptTokens)     || 0) + (Number(dm.promptTokens)     || 0);
        em.candidatesTokens = (Number(em.candidatesTokens) || 0) + (Number(dm.candidatesTokens) || 0);
        em.calls            = (Number(em.calls)            || 0) + (Number(dm.calls)            || 0);
        ex[model] = em;
      });
      existing.tokens = ex;
      existing.sessions = Math.max(Number(existing.sessions) || 0, Number(d.sessions) || 0);
      // Activity timestamps: earliest first, latest last.
      if (d.firstActiveAt) {
        existing.firstActiveAt = existing.firstActiveAt
          ? Math.min(existing.firstActiveAt, d.firstActiveAt)
          : d.firstActiveAt;
      }
      if (d.lastActiveAt) {
        existing.lastActiveAt = existing.lastActiveAt
          ? Math.max(existing.lastActiveAt, d.lastActiveAt)
          : d.lastActiveAt;
      }
    });
  }
  _ingest(remote);
  _ingest(local);
  // 2026-05-18 v25: estCostUSD recomputation removed from here —
  // bundler puts each top-level fn in its own eval scope, so this
  // function can't see sibling etEstimateCost. init.js calls
  // etEstimateCost on each merged day after this returns (it has
  // both helpers in scope via efns).
  var sortedDays = Object.keys(byDate).sort().map(function (k) {
    return byDate[k];
  });
  return {
    // Prefer local's userName/userKey since it reflects the running
    // session's identity; remote is just last-written value.
    userName: (local.userName || remote.userName || ""),
    userKey: (local.userKey || remote.userKey || ""),
    generatedAt: (local.generatedAt || new Date().toISOString()),
    days: sortedDays,
  };
}

// Estimate USD cost from a per-model tokens map: { "<model>": {
// promptTokens, candidatesTokens, calls } }. Returns { totalUSD,
// byModel: { "<model>": usd } }. Caller decides display precision.
// 2026-05-18 v26: price table INLINED — bundler isolates each top-
// level fn into its own eval scope, so this function can't call
// sibling etPriceTable. Keep the two tables identical; etPriceTable
// stays exported for external callers that want just the rates.

engine.etEstimateCost:
function etEstimateCost(tokensMap) {
  var prices = {
    "gemini-3.1-flash-lite-preview":     { in: 0.04, out: 0.20 },
    "gemini-3.1-flash":                  { in: 0.075, out: 0.30 },
    "gemini-2.5-flash":                  { in: 0.075, out: 0.30 },
    "gemini-2.5-flash-lite-preview":     { in: 0.04, out: 0.20 },
    "gemini-2.5-pro":                    { in: 1.25, out: 5.00 },
    "gemini-1.5-pro":                    { in: 1.25, out: 5.00 },
    "gemini-1.5-flash":                  { in: 0.075, out: 0.30 },
    "_default":                          { in: 0.075, out: 0.30 },
  };
  var out = { totalUSD: 0, byModel: {} };
  if (!tokensMap || typeof tokensMap !== "object") return out;
  Object.keys(tokensMap).forEach(function (model) {
    var t = tokensMap[model] || {};
    var price = prices[model] || prices._default;
    var inTok  = Number(t.promptTokens) || 0;
    var outTok = Number(t.candidatesTokens) || 0;
    var usd = (inTok * price.in + outTok * price.out) / 1000000;
    out.byModel[model] = usd;
    out.totalUSD += usd;
  });
  return out;
}

// Build the digest payload pushed to GitHub. Input: array of telemetry
// rows for one user (already pruned). Output: { userName, userKey,
// generatedAt, days } where days is ordered ascending by date.
// 2026-05-17: each day now also carries `tokens` (per-model breakdown)
// and `estCostUSD` (computed from etPriceTable above).

engine.etBuildDigest:
function etBuildDigest(rows, userName, userKey) {
  var sorted = (Array.isArray(rows) ? rows : []).slice().sort(function (a, b) {
    return String(a.date || "").localeCompare(String(b.date || ""));
  });
  return {
    userName: String(userName || ""),
    userKey: String(userKey || ""),
    generatedAt: new Date().toISOString(),
    days: sorted.map(function (r) {
      var tokensMap = r.tokens || {};
      // 2026-05-18 v25: estCostUSD computed in init.js after this
      // returns — bundler isolates each top-level fn so sibling
      // etEstimateCost isn't visible from here. Stub the field
      // (init.js will overwrite via the engine helper).
      return {
        date: r.date || "",
        toolsUsed: r.toolsUsed || {},
        sessions: Number(r.sessions || 0),
        firstActiveAt: Number(r.firstActiveAt || 0),
        lastActiveAt: Number(r.lastActiveAt || 0),
        tokens: tokensMap,
        estCostUSD: 0,
      };
    }),
  };
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.bus || !eli.storage || !eli.compat) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded.eli_telemetry;
  if (!bundle) return;

  var efns = bundle._eliEngineFns || {};
  var etUserKey       = efns.etUserKey;
  var etTodayInfo     = efns.etTodayInfo;
  var etDeriveToolName= efns.etDeriveToolName;
  var etRowsToPrune   = efns.etRowsToPrune;
  var etBuildDigest   = efns.etBuildDigest;
  var etUserInitials  = efns.etUserInitials;
  var etMergeDigests  = efns.etMergeDigests;
  var etEstimateCost  = efns.etEstimateCost;
