    if (!digest || !Array.isArray(digest.days) || typeof etEstimateCost !== "function") return digest;
    digest.days.forEach(function (d) {
      var cost = etEstimateCost(d.tokens || {});
      d.estCostUSD = (cost && typeof cost.totalUSD === "number") ? Number(cost.totalUSD.toFixed(6)) : 0;
    });
    return digest;
  }
  if (!etUserKey || !etTodayInfo || !etDeriveToolName || !etRowsToPrune || !etBuildDigest) {
    eli.log.event("telemetry", "load_failed", {
      hasUserKey: !!etUserKey, hasToday: !!etTodayInfo,
      hasDerive: !!etDeriveToolName, hasPrune: !!etRowsToPrune,
      hasDigest: !!etBuildDigest,
    });
    return;
  }
  // 2026-05-17 v21: fallback shim — if the engine bundle hasn't been
  // rebuilt with etUserInitials yet, derive initials inline.
  if (typeof etUserInitials !== "function") {
    etUserInitials = function (ident) {
      if (!ident || typeof ident !== "object") return "";
      var first = String(ident.firstName || "").trim();
      var fi = first ? first.charAt(0).toUpperCase() : "";
      var full = String(ident.name || "").trim();
      var parts = full.split(/\s+/).filter(Boolean);
      var li = "";
      if (parts.length >= 2) {
        var last = parts[parts.length - 1];
        if (last) li = last.charAt(0).toUpperCase();
      }
      return fi + li;
    };
  }

  var STORE_CONFIG = "config";
  var ROW_PREFIX = "_telemetry_";
  var CONSENT_KEY = "_telemetry_consent";
  var LAST_PUSH_KEY = "_telemetry_last_push_at";
  var PUSH_THROTTLE_MS = 12 * 60 * 60 * 1000; // 12h
  var GITHUB_OWNER = "apndrewn";
  var GITHUB_REPO  = "eli-data";

  // Session debounce — only count one "session" per row per boot.
  var _sessionMarkedForDate = null;

  // ─── Consent gate (2026-05-17 — dialog removed) ─────────────────
  // Default = opted_in (no first-run dialog). User can opt out via
  // Settings → Telemetry toggle; the card description there carries
  // the disclosure text ("what's sent, how often, where it goes").
  // Three states: "opted_in" | "opted_out" | unset (treated as opted_in).
  function _readConsent() {
    try {
      var v = String(eli.compat.lsGet(CONSENT_KEY) || "").trim();
