      // the disclosure surface; explicit opt-out persists "opted_out".
      return v || "opted_in";
    } catch (e) { return "opted_in"; }
  }
  function _writeConsent(value) {
    try { eli.compat.lsSet(CONSENT_KEY, String(value)); } catch (e) {}
  }

  // ─── Identity helpers ──────────────────────────────────────────────
  function _currentIdentity() {
    try {
      if (eli.tools && typeof eli.tools.userIdentity === "function") {
        return eli.tools.userIdentity() || {};
      }
    } catch (e) {}
    return {};
  }
  function _currentUserKey() {
    return etUserKey(_currentIdentity());
  }

