    // another "everything looked fine but nothing wrote" episode.
    return eli.storage.put(STORE_CONFIG, row).then(function () { return true; })
      .catch(function (e) {
        eli.log.event("telemetry", "save_failed", { msg: (e && e.message) || String(e), key: row && row.key });
        return false;
      });
  }
