    // Nemiroff), never the full first name.
    var initials = etUserInitials(ident);
    var rowId = _rowKey(userKey, info.date);
    var now = Date.now();
    return _loadRow(userKey, info.date).then(function (existing) {
      var row = existing || {
        key: rowId,  // 2026-05-18 v25: config-store keyPath is "key", not "id".
        userKey: userKey,
        userName: initials,
        date: info.date,
        toolsUsed: {},
        sessions: 0,
        firstActiveAt: now,
        lastActiveAt: now,
      };
