      if (!row.key && row.id) row.key = row.id;
      // Refresh userName (overwrite — was previously only-if-empty;
      // now always refresh so old full-name rows upgrade to initials).
      if (initials) row.userName = initials;
      row.toolsUsed = row.toolsUsed || {};
      row.toolsUsed[toolName] = (Number(row.toolsUsed[toolName]) || 0) + 1;
      row.lastActiveAt = now;
      if (!row.firstActiveAt) row.firstActiveAt = now;
      // Debounce session counter: one per boot per date.
      if (_sessionMarkedForDate !== info.date) {
        row.sessions = (Number(row.sessions) || 0) + 1;
        _sessionMarkedForDate = info.date;
      }
      return _saveRow(row).then(function () {
        // Fire-and-forget prune; failures are non-fatal.
        _pruneOld(userKey, info.date).catch(function () {});
        return true;
      });
    });
  }

