    if (!payload || !payload.name) return;
    var tool = etDeriveToolName(payload.name);
    if (!tool) return;
    _recordToolLaunch(tool).catch(function (e) {
      eli.log.event("telemetry", "record_failed", { msg: e && e.message });
    });
  }

