  // (eli.ai._attempt). Accumulates per-model promptTokens + candidatesTokens
  // + call counts onto the same daily row as tool launches. Cost is
  // computed at digest-build time via etEstimateCost (engine helper) so
  // we never store stale dollar amounts.
  function _recordTokensUsed(payload) {
    if (!payload || !payload.model) return Promise.resolve(false);
    var info = etTodayInfo();
