    // change in _recordToolLaunch above).
    var ident = _currentIdentity();
    var userKey = etUserKey(ident);
    if (!userKey) return Promise.resolve(false);
    var initials = etUserInitials(ident);
    var rowId = _rowKey(userKey, info.date);
    var now = Date.now();
    var model = String(payload.model);
    var inTok  = Number(payload.promptTokens) || 0;
    var outTok = Number(payload.candidatesTokens) || 0;
    return _loadRow(userKey, info.date).then(function (existing) {
