  // PUT digest to usage/<userkey>.json. Creates on first call, updates after.
  function _githubPut(pat, userKey, digest, existingSha) {
    var filePath = "usage/" + encodeURIComponent(userKey) + ".json";
    var url = "https://api.github.com/repos/" + GITHUB_OWNER + "/" + GITHUB_REPO +
      "/contents/" + filePath;
    var content = JSON.stringify(digest, null, 2);
    var body = {
      message: "Usage update " + new Date().toISOString(),
      content: _strToB64(content),
    };
    if (existingSha) body.sha = existingSha;
    return fetch(url, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (!r.ok) {
        return r.text().then(function (t) {
          throw new Error("PUT failed: HTTP " + r.status + " · " + String(t).slice(0, 200));
        });
      }
      return r.json().then(function () { return true; });
    });
  }

  // Build digest from IDB, push to GitHub. Throttled by lastPush unless force=true.
  // Resolves with { ok, skipped?, reason?, days? } — never throws.
  function _push(opts) {
    opts = opts || {};
    var force = !!opts.force;
    var ident = _currentIdentity();
    var userKey = etUserKey(ident);
    if (!userKey) {
      return Promise.resolve({ ok: false, skipped: true, reason: "no_user_key" });
    }
    var pat = _getPat();
    if (!pat) {
      return Promise.resolve({ ok: false, skipped: true, reason: "no_pat" });
    }
    if (!force) {
      var lastStr = eli.compat.lsGet(LAST_PUSH_KEY);
      var lastNum = lastStr ? Number(lastStr) : 0;
      if (lastNum && (Date.now() - lastNum) < PUSH_THROTTLE_MS) {
        return Promise.resolve({ ok: false, skipped: true, reason: "throttled" });
      }
    }
    return _allUserRows(userKey).then(function (rows) {
      // 2026-05-17 v23: when there are zero rows, run a synthetic
      // _recordToolLaunch("force_push_self_test") to prove whether
      // the write path itself is working. If the self-test row lands,
      // we know IDB writes work — the issue is that real launches
      // aren't reaching _recordToolLaunch (most likely: consent
      // opted_out → bus subscription never happened). The self-test
      // row is captured in the diagnostic so the user sees it.
      var didSelfTest = false;
      var selfTestOk = null;
      var didSelfTestPromise = Promise.resolve(rows);
      if ((rows || []).length === 0) {
        didSelfTest = true;
        didSelfTestPromise = _recordToolLaunch("force_push_self_test")
          .then(function (ok) { selfTestOk = !!ok; })
          .catch(function () { selfTestOk = false; })
          .then(function () { return _allUserRows(userKey); });
      }
      return didSelfTestPromise.then(function (rowsAfterSelfTest) {
        var digest = etBuildDigest(rowsAfterSelfTest, etUserInitials(ident), userKey);
        var isWeekendToday = false;
        try { isWeekendToday = !!(etTodayInfo && etTodayInfo().isWeekend); } catch (_) {}
        var consentState = _readConsent();
        return eli.storage.getAll(STORE_CONFIG).then(function (allConfig) {
          var allTelemetryRows = (allConfig || []).filter(function (r) {
            return r && typeof r.key === "string" && r.key.indexOf(ROW_PREFIX) === 0;
          });
          var otherUserKeys = {};
          allTelemetryRows.forEach(function (r) {
            var trimmed = r.key.slice(ROW_PREFIX.length);
            var lastUnd = trimmed.lastIndexOf("_");
            if (lastUnd > 0) {
              var k = trimmed.slice(0, lastUnd);
              if (k !== userKey) otherUserKeys[k] = (otherUserKeys[k] || 0) + 1;
            }
          });
          return _githubGetSha(pat, userKey).then(function (info) {
            var sha = info && info.sha;
            // 2026-05-18 v25: MERGE the remote digest with the local
            // one before PUT. Handles the multi-computer case where
            // ELI runs on two machines under the same userKey —
            // without merging, each push overwrites the other.
            var remoteDigest = info && info.digest;
            var mergedDigest = (typeof etMergeDigests === "function")
              ? etMergeDigests(remoteDigest, digest)
              : digest;
            _stampCosts(mergedDigest);
            return _githubPut(pat, userKey, mergedDigest, sha).then(function () {
              try { eli.compat.lsSet(LAST_PUSH_KEY, String(Date.now())); } catch (e) {}
              eli.log.event("telemetry", "pushed", { days: mergedDigest.days.length, userKey: userKey, rowCount: rowsAfterSelfTest.length, remoteDays: (remoteDigest && remoteDigest.days ? remoteDigest.days.length : 0) });
              return {
                ok: true,
                days: mergedDigest.days.length,
                localDays: digest.days.length,
                remoteDays: (remoteDigest && remoteDigest.days ? remoteDigest.days.length : 0),
                rowCount: (rowsAfterSelfTest || []).length,
                userKey: userKey,
                consent: consentState,
                didSelfTest: didSelfTest,
                selfTestOk: selfTestOk,
                isWeekendToday: isWeekendToday,
                otherUserKeys: otherUserKeys,
                bootState: window._eliTelemetryBoot || null,
                reason: mergedDigest.days.length === 0
                  ? (isWeekendToday ? "no_data_weekend" : "no_data_weekday")
                  : null,
              };
            });
          });
        });
      });
    }).catch(function (err) {
      // 2026-05-18 v25: surface the actual error message so callers
      // (Settings UI) can show what failed instead of a bare
      // "push_failed". Most common downstream cause is GitHub auth
      // (PAT expired/missing) or network — both produce informative
      // messages we should show the user.
      var em = (err && err.message) || String(err);
      eli.log.event("telemetry", "push_failed", { msg: em });
      return { ok: false, skipped: true, reason: "push_failed", error: em };
    });
  }

  // ─── Public dispatch surface ───────────────────────────────────────
  function _telemetryPush() {
    return _push({ force: true });
  }
  function _telemetryStatus() {
    var userKey = _currentUserKey();
    var consent = _readConsent();
    var lastPushStr = eli.compat.lsGet(LAST_PUSH_KEY);
    var lastPush = lastPushStr ? Number(lastPushStr) : 0;
    if (!userKey) {
      return Promise.resolve({
        userKey: null, consent: consent, lastPushAt: lastPush, dayCount: 0,
      });
    }
    return _allUserRows(userKey).then(function (rows) {
      return {
        userKey: userKey,
        consent: consent,
        lastPushAt: lastPush,
        dayCount: (rows || []).length,
      };
    });
  }

  eli.register({
    telemetry: {
      push: _telemetryPush,
      status: _telemetryStatus,
    },
  });

  // ─── Consent migration v2 (2026-05-17) ───────────────────────────
  // One-time: clear any "opted_out" value persisted before the default
  // flipped to opt-in. Most of those opt-outs came from the (now-
  // removed) first-run dialog, which most users dismissed reflexively.
  // After migration, the Settings → Global → Usage Telemetry toggle is
  // the authoritative opt-out path; a fresh "opted_out" set AFTER this
  // marker exists is honored permanently.
  function _migrateConsentV2() {
    try {
      if (eli.compat.lsGet("_telemetry_migration_v2")) return;
      var cur = String(eli.compat.lsGet(CONSENT_KEY) || "").trim();
      if (cur === "opted_out") {
        eli.compat.lsRemove(CONSENT_KEY);
        eli.log.event("telemetry", "consent_migrated_to_default_on", {});
      }
      eli.compat.lsSet("_telemetry_migration_v2", "1");
    } catch (e) { /* tolerate */ }
  }

  // ─── Boot sequence (default opt-in, no dialog) ───────────────────
  // 2026-05-17 v24: boot-state observability. Each step writes to
  // window._eliTelemetryBoot so the push diagnostic can surface
  // exactly where boot bailed. Was opaque before — silent fail to
  // subscribe looked identical to "no events ever fired."
  window._eliTelemetryBoot = { step: "init", subscribed: false, error: null };
  function _bootStart() {
    try {
      window._eliTelemetryBoot.step = "consent_migration";
      _migrateConsentV2();
      window._eliTelemetryBoot.step = "consent_check";
      if (_readConsent() === "opted_out") {
        eli.log.event("telemetry", "skipped_opted_out", {});
        window._eliTelemetryBoot.step = "skipped_opted_out";
        return;
      }
      window._eliTelemetryBoot.step = "subscribing_stats";
      eli.bus.on("stats:recorded", _onStatsRecorded);
      window._eliTelemetryBoot.step = "subscribing_tokens";
      eli.bus.on("ai:tokens_used", _onTokensUsed);
      window._eliTelemetryBoot.subscribed = true;
      window._eliTelemetryBoot.step = "subscribed";
      eli.log.event("telemetry", "subscribed", {});
      // Defer the push so the dashboard finishes painting first.
      setTimeout(function () {
        _push({ force: false }).then(function (r) {
          if (r && r.ok) eli.log.event("telemetry", "boot_push_ok", { days: r.days });
        });
      }, 5000);
    } catch (e) {
      window._eliTelemetryBoot.error = (e && e.message) || String(e);
      eli.log.event("telemetry", "boot_failed", { step: window._eliTelemetryBoot.step, msg: window._eliTelemetryBoot.error });
    }
  }

  _bootStart();
  eli.log.event("tool", "eli_telemetry_initialized", { bootStep: window._eliTelemetryBoot.step, subscribed: window._eliTelemetryBoot.subscribed });
}
